"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[763],{763:(e,n,i)=>{i.r(n),i.d(n,{content:()=>d,description:()=>t,title:()=>s});i(43);var r=i(579);const s="Praktisches Lernen: Virtuelle Sektion einer Niere verbessert Engagement von Studierenden mit besonderen Bed\xfcrfnissen ",t="Entdecken sie, wie Whimsylabs physische Interaktion in der virtuellen Umgebung die Bildungsergebnisse und das Engagement f\xfcr Studierende mit besonderen Bed\xfcrfnissen erheblich verbessert.",d=(0,r.jsxs)("div",{children:[(0,r.jsx)("p",{children:"Die menschliche Niere spielt eine wichtige Rolle bei der Aufrechterhaltung der Hom\xf6ostase, filtert Blut, h\xe4lt das Gleichgewicht von Fl\xfcssigkeiten und Elektrolyte und filtert Abfallstoffe. Die menschlichen Nieren verarbeiten t\xe4glich etwa 180 Liter Filtrat und demonstrieren die bemerkenswerte Effizienz dieser komplexen Organe. Doch f\xfcr viele Studierende k\xf6nnen die Komplexit\xe4t und Funktionsweisen dieser feinen Mechanismen schwierig zu verstehen sein. Whimsylabs' hochmoderne Virtual-Reality-Plattform geht diese Herausforderung durch branchenf\xfchrende Nierensektionssimulation an, die fortschrittliche physisch-interaktive Sektionswerkzeuge und ausgekl\xfcgelte Mikroskopsimulationstechnologie bietet, die auf dem Bildungsmarkt un\xfcbertroffen sind."}),(0,r.jsx)("p",{children:"Im Gegensatz zu herk\xf6mmlichen VR-Laboren, die Studierende passiv durch einen Prozess f\xfchren, \xfcbergibt unsere Laborerfahrung die volle Kontrolle. Teilnehmende manipulieren physisch Laborwerkzeuge mit nat\xfcrlichen Handbewegungen, machen Einschnitte in virtuelles Gewebe und untersuchen mikroskopische Anatomie durch detaillierte Mikroskopfunktionen. Das Ergebnis ist eine aktive Lernerfahrung, die visuelle, auditive und kin\xe4sthetische Eingaben in Echtzeit kombiniert. Forschung in der Anatomielehre zeigt, dass interaktive, dreidimensionale Lernumgebungen das r\xe4umliche Verst\xe4ndnis und den langfristigen Wissensabruf im Vergleich zu traditionellen lehrbuchbasierten Ans\xe4tzen erheblich verbessern. Aktive Lernans\xe4tze wie unsere haben gezeigt, dass sie die Studentenleistung in MINT-Bereichen steigern."}),(0,r.jsx)("div",{className:"video-container",children:(0,r.jsx)("iframe",{width:"100%",height:"400",src:"https://www.youtube.com/embed/nhZN6WCWtAk",title:"WhimsyLabs Virtual Kidney Dissection",frameBorder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowFullScreen:!0})}),(0,r.jsx)("p",{className:"caption",children:"Whimsylabs' Demonstration der virtuellen Nierensektion, die neben der physischen Interaktion auch p\xe4dagogische Erz\xe4hlung beinhaltet."}),(0,r.jsx)("p",{children:"Immersive VR-Lernumgebungen wie unsere haben gezeigt, dass sie das Engagement und Verst\xe4ndnis verbessern, indem sie eine gr\xf6\xdfere Anzahl neuronale Bahnen gleichzeitig anregen und sowohl das Ged\xe4chtnis als auch das konzeptionelle Verst\xe4ndnis verbessern. In unserer Simulation verwenden Teilnehmer ein virtuelles Skalpell mit nat\xfcrlicher Griffmechanik, sp\xfcren haptisches Feedback w\xe4hrend der Sektion, und positionieren die Niere physisch unter einem Mikroskop f\xfcr weitere Untersuchungen."}),(0,r.jsx)("img",{src:"/images/kidney_barclays.jpg",alt:"Participants engaging with the Whimsylabs kidney dissection at Barclays Headquarters",className:"rounded shadow center limited-size"}),(0,r.jsx)("p",{className:"caption",children:"Unsere Demonstration im Barclays-Hauptsitz sch\xe4rfte das Bewusstsein f\xfcr die Nierenfunktion und Organspende durch ansprechende, praktische Erkundung."}),(0,r.jsx)("p",{children:"Die Demo wurde im Barclays-Hauptsitz in London als Teil einer Kampagne zur Sensibilisierung f\xfcr Nierengesundheit und Organspende vorgestellt. Teilnehmende von verschiedensten Hintergr\xfcnden konnten die Anatomie der Niere im Detail erkunden, und beobachten, wie das Blut durch die Nierenarterie eintritt, gefiltert wird und durch die Nierenvene wieder austritt. Beim weiteren Hineinzoomen mit dem Mikroskop in die Nephrone konnten sie untersuchen, wie die Filtration am Glomerulus stattfindet und wie Wasser und Harnstoff durch die Henle-Schleife und Sammelg\xe4nge verarbeitet werden. Jede Niere enth\xe4lt etwa eine Million Nephrone, die funktionellen Einheiten, die f\xfcr den Filtrationsprozess verantwortlich sind, was die bemerkenswerte Komplexit\xe4t der Nierenphysiologie hervorhebt."}),(0,r.jsx)("p",{children:"Dieses Format zeigt nicht nur die Anatomie, es f\xf6rdert auch tiefere Neugier. Die F\xe4higkeit, direkt mit den Inhalten zu interagieren, anstatt passiv zuschauen oder zu zuzuh\xf6ren, verbessert das konzeptionelle Verst\xe4ndnis und die Abrufbarkeit des Wissens. Benutzerinnen und Benutzer k\xf6nnen Aktionen wiederholen, die Komponenten einzeln manipulieren und das System in ihrem eigenen Tempo erkunden, wordurch insbesondere das individualisierte Lernen unterst\xfctzt wird."}),(0,r.jsx)("p",{children:"Unser Ansatz ist besonders wirkungsvoll f\xfcr Studenten mit besonderen Bildungsbed\xfcrfnissen und Behinderungen. Die Forschung legt nahe, dass multisensorische Lernumgebungen das Verst\xe4ndnis und die Motivation f\xfcr Lernende mit besonderen Bed\xfcrfnissen verbessern, besonders wenn Aufgaben interaktiv und selbstbestimmt sind. Durch die Kombination von physischer Bewegung mit visueller und auditiver Eingabe schafft die Sektion von Whimsylabs eine speziell gef\xf6rderte Lernerfahrung, die sich an die verschiedenen Lernprofile der Nutzenden anpasst."}),(0,r.jsx)("p",{children:"Lehrkr\xe4fte haben berichtet, dass Studierende mit Aufmerksamkeits- oder Verarbeitungsherausforderungen von der F\xe4higkeit profitieren, sich auf einen Schritt nach dem anderen zu konzentrieren, komplexe Aktionen zu wiederholen und Feedback durch Bewegung und auditive Hinweise zu erhalten. Im Gegensatz zu statischen Diagrammen oder Videovorlesungen verwandelt unser Format abstrakte Strukturen in greifbare Systeme, die erkundet, hinterfragt und verstanden werden k\xf6nnen. Forschung zum universellen Design des Lernens betont die Bedeutung der Bereitstellung mehrerer Wege und Darstellungsmittel, des Engagements und des Ausdrucks, um pers\xf6nliche Lernbed\xfcrfnisse zu ber\xfccksichtigen."}),(0,r.jsx)("p",{children:"Was Whimsylabs auszeichnet, ist, dass wir Inhalte nicht vereinfachen, sondern komplexe Systeme auf zug\xe4ngliche, interaktive Weise pr\xe4sentieren. Die vollst\xe4ndige Sektion deckt die gleichen anatomischen Details und Physiologie ab wie eine echte Laborsitzung, aber es geschieht auf unsere besondere Weise, die f\xfcr mehr Studierende konsistenter funktioniert. Ob f\xfcr Schulen, \xd6ffentlichkeitsarbeit oder barrierefreie Bildung, unser Modell bringt Wissenschaft in Reichweite."})]})}}]);
